import { useEffect, useMemo, useState, type ButtonHTMLAttributes, type FormEvent, type ReactNode } from "react";
import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
import { Link, Route, Router, Switch, useLocation, useParams } from "wouter";
import {
  ArrowRight, CalendarDays, Check, ChevronLeft, ChevronRight, Compass, Copy, Flag, Gem,
  Info, Landmark, Link2, Loader2, LockKeyhole, Map, Menu, MessageCircle, Pencil, Plus,
  RefreshCw, Settings2, ShieldCheck, Sparkles, Star, Target, Trophy, UsersRound, X, Zap,
} from "lucide-react";
import {
  getGetGameStateQueryKey, getGetRoomQueryKey, useCreateEncouragement, useCreateLabel,
  useCreateQuest, useCreateReward, useCreateRewardRequest, useCreateRoom, useDeleteLabel, useDeleteQuest,
  useDeleteReward, useGetGameState, useGetRoom, useJoinRoom, useRedeemReward,
  useRespondToRewardRequest, useSetQuestCompleted, useSetQuestReward, useUpdateLabel,
  useUpdateQuest, useUpdateReward,
} from "@workspace/api-client-react";
import type { GameState, Label, Player, Quest, QuestLink, QuestSubtask, Reward, RewardRequest } from "@workspace/api-client-react";
import { ErrorBoundary } from "@/components/error-boundary";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import NotFound from "@/pages/not-found";
import "./index.css";

const queryClient = new QueryClient();
const today = new Date().toISOString().slice(0, 10);
const playerPalette = ["#d79b4c", "#6f9f8b"];
const labelPalette = ["#6f9f8b", "#d79b4c", "#9a7bb5", "#d26f67", "#5d8fb5", "#c17b55"];
const dateAtNoon = (value: string) => new Date(`${value}T12:00:00`);
const shiftDate = (value: string, amount: number) => {
  const date = dateAtNoon(value);
  date.setDate(date.getDate() + amount);
  return date.toISOString().slice(0, 10);
};
const dateLabel = (value: string) => dateAtNoon(value).toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" });
const weekLabel = (value: string) => `${dateAtNoon(value).toLocaleDateString(undefined, { month: "short", day: "numeric" })} – ${dateAtNoon(shiftDate(value, 6)).toLocaleDateString(undefined, { month: "short", day: "numeric" })}`;
const inviteLink = (id: string) => `${window.location.origin}/room/${id}`;

function initials(name: string) { return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }
function playerColor(player: Player | undefined, players: Player[]) { return player?.color ?? playerPalette[Math.max(0, players.findIndex((item) => item.id === player?.id)) % 2] ?? playerPalette[0]; }
function ownerOf(state: GameState, id: string) { return state.players.find((player) => player.id === id); }
function meId() { return localStorage.getItem("quest-road-player") ?? ""; }
function refreshRoom(roomId: string) { queryClient.invalidateQueries({ queryKey: getGetGameStateQueryKey(roomId) }); }

function Avatar({ player, players = [], size = "md" }: { player?: Player | null; players?: Player[]; size?: "sm" | "md" | "lg" }) {
  const sizes = { sm: "h-7 w-7 text-[10px]", md: "h-9 w-9 text-xs", lg: "h-12 w-12 text-sm" };
  return <div className={`${sizes[size]} grid shrink-0 place-items-center rounded-full border-2 border-background font-extrabold text-white shadow-sm`} style={{ backgroundColor: playerColor(player ?? undefined, players) }}>{player ? initials(player.name) : "?"}</div>;
}
function Button({ children, className = "", variant = "primary", ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "secondary" | "ghost" | "danger" }) {
  const styles = { primary: "bg-[#f7ca56] text-[#24243b] shadow-[0_3px_0_#c4962b] hover:-translate-y-0.5", secondary: "bg-[#302f48] text-[#fff7e8] shadow-[0_3px_0_#1d1d31]", ghost: "border border-[#d9cfbd] bg-transparent text-[#3e3a4e] hover:bg-[#ebe3d4]", danger: "bg-[#f3d5d0] text-[#9f433e] hover:bg-[#efc3bd]" };
  return <button {...props} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}
function Loading({ text = "Loading the shared room…" }: { text?: string }) { return <div className="flex min-h-[300px] items-center justify-center"><div className="text-center text-muted-foreground"><div className="mx-auto h-10 w-10 animate-pulse-soft rounded-full border-4 border-[#f7ca56] border-t-transparent" /><p className="mt-3 text-sm font-semibold">{text}</p></div></div>; }
function ErrorState({ retry }: { retry?: () => void }) { return <div className="mx-auto max-w-md py-20 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#f3d5d0] text-[#9f433e]"><Info /></div><h2 className="mt-4 font-display text-2xl font-bold">The room went quiet</h2><p className="mt-2 text-sm text-muted-foreground">We couldn’t load this shared journey.</p>{retry && <Button variant="ghost" onClick={retry} className="mt-5"><RefreshCw className="h-4 w-4" /> Try again</Button>}</div>; }
function Empty({ icon: Icon, title, body, action }: { icon: typeof Compass; title: string; body: string; action?: ReactNode }) { return <div className="texture-grid flex min-h-[220px] flex-col items-center justify-center rounded-2xl border border-dashed border-[#d7cbb8] bg-[#f8f1e5] p-7 text-center"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#ece1cf] text-[#7f7664]"><Icon /></div><h3 className="mt-4 font-display text-xl font-bold">{title}</h3><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{body}</p>{action && <div className="mt-4">{action}</div>}</div>; }
function PageHeader({ eyebrow, title, body, action }: { eyebrow: string; title: string; body: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mb-2 font-mono-ui text-[11px] tracking-[.2em] text-[#9a7a2b] uppercase">{eyebrow}</p><h1 className="font-display text-4xl font-bold tracking-[-.045em] sm:text-5xl">{title}</h1><p className="mt-3 max-w-xl text-sm leading-6 text-muted-foreground">{body}</p></div>{action}</div>; }

function HomePage() {
  const [, setLocation] = useLocation(); const create = useCreateRoom();
  const makeRoom = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const name = String(data.get("name") ?? "").trim(); const room = String(data.get("room") ?? "").trim(); if (!name || !room) return; create.mutate({ data: { name: room, playerName: name } }, { onSuccess: (result) => { localStorage.setItem("quest-road-room", result.id); localStorage.setItem("quest-road-player", result.host.id); setLocation(`/room/${result.id}`); } }); };
  const join = useJoinRoom(); const submitJoin = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const name = String(data.get("name") ?? "").trim(); const code = String(data.get("code") ?? "").trim(); if (!name || !code) return; join.mutate({ roomId: code, data: { code, playerName: name } }, { onSuccess: (room) => { localStorage.setItem("quest-road-room", room.id); localStorage.setItem("quest-road-player", room.guest?.id ?? ""); setLocation(`/room/${room.id}`); } }); };
  const [mode, setMode] = useState<"create" | "join">("create");
  return <main className="min-h-[100dvh] overflow-hidden bg-[#24243b] text-[#fff7e8]"><div className="absolute inset-0 opacity-40" style={{ backgroundImage: "radial-gradient(circle at 75% 15%, #f7ca56 0, transparent 17%), radial-gradient(circle at 15% 82%, #476b67 0, transparent 24%)" }} /><div className="relative mx-auto flex min-h-[100dvh] max-w-7xl flex-col px-5 py-5 sm:px-10 sm:py-8"><header className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f7ca56] text-[#24243b]"><Compass className="h-5 w-5" /></span><span className="font-display text-lg font-bold">Quest Buddies</span></header><div className="grid flex-1 items-center gap-12 py-12 lg:grid-cols-[1fr_440px] lg:gap-20"><section className="max-w-2xl"><p className="mb-6 font-mono-ui text-xs tracking-[.24em] text-[#f7ca56] uppercase">A cooperative browser game</p><h1 className="font-display text-5xl font-bold leading-[.98] tracking-[-.05em] sm:text-7xl">Make plans.<br /><span className="text-[#f7ca56]">Keep each other</span><br />moving.</h1><p className="mt-7 max-w-lg text-base leading-7 text-[#bdbaca] sm:text-lg">Two players, personal tasks, shared rewards, and a clear view of what needs attention.</p><div className="mt-10 flex flex-wrap gap-6 text-sm text-[#d7d3df]"><span className="flex items-center gap-2"><UsersRound className="h-4 w-4 text-[#f7ca56]" /> Exactly two players</span><span className="flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-[#78b29d]" /> Private room</span></div></section><section className="rounded-3xl bg-[#fff7e8] p-6 text-[#24243b] shadow-[0_22px_60px_rgba(9,10,28,.35)] sm:p-8"><div className="mb-7 flex gap-1 rounded-xl bg-[#eee5d5] p-1"><button onClick={() => setMode("create")} className={`flex-1 rounded-lg px-3 py-2 text-sm font-bold ${mode === "create" ? "bg-[#302f48] text-[#fff7e8]" : "text-[#797388]"}`}>Start a room</button><button onClick={() => setMode("join")} className={`flex-1 rounded-lg px-3 py-2 text-sm font-bold ${mode === "join" ? "bg-[#302f48] text-[#fff7e8]" : "text-[#797388]"}`}>Join a room</button></div>{mode === "create" ? <form onSubmit={makeRoom} className="space-y-4"><h2 className="font-display text-2xl font-bold">Start a room</h2><label className="block text-sm font-bold">Room name<input name="room" placeholder="Sunday Side Quests" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Your name<input name="name" placeholder="What should we call you?" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><Button type="submit" className="w-full">Create room <ArrowRight className="h-4 w-4" /></Button></form> : <form onSubmit={submitJoin} className="space-y-4"><h2 className="font-display text-2xl font-bold">Join your buddy</h2><label className="block text-sm font-bold">Invite code<input name="code" placeholder="ROAD-7K2M" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 font-mono-ui uppercase tracking-[.18em] outline-none focus:border-[#c4962b]" /></label><label className="block text-sm font-bold">Your name<input name="name" placeholder="What should they call you?" className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3 outline-none focus:border-[#c4962b]" /></label><Button type="submit" disabled={join.isPending} className="w-full">{join.isPending ? <Loader2 className="animate-spin" /> : <>Join room <ArrowRight className="h-4 w-4" /></>}</Button></form>}</section></div></div></main>;
}

const nav = [{ href: "/today", label: "Updates", icon: MessageCircle }, { href: "/tasks", label: "My tasks", icon: Target }, { href: "/journey", label: "Journey", icon: Map }, { href: "/calendar", label: "Calendar", icon: CalendarDays }, { href: "/rewards", label: "Rewards", icon: Trophy }, { href: "/together", label: "Together", icon: UsersRound }];
function Shell({ state, children }: { state: GameState; children: ReactNode }) { const [open, setOpen] = useState(false); const [location] = useLocation(); const me = ownerOf(state, meId()) ?? state.players[0]; return <div className="min-h-[100dvh] bg-[#f3ecdf] text-[#302f48]"><aside className={`fixed inset-y-0 left-0 z-30 flex w-[260px] flex-col bg-[#24243b] px-5 py-6 text-[#fff7e8] transition-transform lg:translate-x-0 ${open ? "translate-x-0" : "-translate-x-full"}`}><Link href="/today" onClick={() => setOpen(false)} className="mb-10 flex items-center gap-3 px-2"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#f7ca56] text-[#24243b]"><Compass className="h-5 w-5" /></span><span className="font-display text-lg font-bold">Quest Buddies</span></Link><div className="mb-7 rounded-2xl border border-[#ffffff12] bg-[#ffffff09] p-3"><div className="flex items-center gap-3"><Avatar player={me} players={state.players} /><div><p className="truncate text-sm font-bold">{me?.name}</p><p className="font-mono-ui text-[10px] text-[#aaa9ba]">{me?.coins ?? 0} coins · {me?.xp ?? 0} XP</p></div></div></div><nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold ${location === href ? "bg-[#f7ca56] text-[#24243b]" : "text-[#aaa9ba] hover:bg-[#ffffff0d] hover:text-[#fff7e8]"}`}><Icon className="h-[18px] w-[18px]" />{label}</Link>)}</nav><Link href="/settings" className="mt-auto flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold text-[#aaa9ba]"><Settings2 className="h-[18px] w-[18px]" />Settings</Link></aside>{open && <button aria-label="Close menu" onClick={() => setOpen(false)} className="fixed inset-0 z-20 bg-[#24243b]/45 lg:hidden" />}<div className="lg:pl-[260px]"><header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-[#ddd1bf] bg-[#f3ecdf]/90 px-5 backdrop-blur-md sm:px-8"><button onClick={() => setOpen(true)} className="rounded-lg p-2 lg:hidden"><Menu className="h-5 w-5" /></button><span className="hidden text-xs font-bold text-[#858072] sm:block">{state.room.name}</span><div className="ml-auto flex -space-x-2">{state.players.map((player) => <Avatar key={player.id} player={player} players={state.players} size="sm" />)}</div></header><main className="mx-auto max-w-[1280px] px-5 py-7 sm:px-8 sm:py-10">{children}</main></div></div>; }

function LabelEditor({ state, onDone }: { state: GameState; onDone: () => void }) { const id = meId(); const labels = state.labels.filter((label) => label.ownerId === id); const [name, setName] = useState(""); const [color, setColor] = useState(labelPalette[0]); const [editing, setEditing] = useState<Label>(); const create = useCreateLabel(); const update = useUpdateLabel(); const remove = useDeleteLabel(); const save = (event: FormEvent) => { event.preventDefault(); if (!name.trim()) return; const data = { ownerId: id, name: name.trim(), color }; const done = () => { setName(""); setEditing(undefined); refreshRoom(state.room.id); }; editing ? update.mutate({ roomId: state.room.id, labelId: editing.id, data }, { onSuccess: done }) : create.mutate({ roomId: state.room.id, data }, { onSuccess: done }); }; return <div className="fixed inset-0 z-50 grid place-items-center bg-[#24243b]/55 p-4"><div className="w-full max-w-md rounded-3xl bg-[#fffaf1] p-6"><div className="flex justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">Task labels</p><h2 className="font-display text-2xl font-bold">Personal labels</h2></div><Button variant="ghost" onClick={onDone}>Done</Button></div><div className="my-5 space-y-2">{labels.map((label) => <div key={label.id} className="flex items-center gap-3 rounded-xl border border-[#e5dacb] p-2.5"><span className="h-3 w-3 rounded-full" style={{ backgroundColor: label.color }} /><span className="flex-1 font-bold">{label.name}</span><Button variant="ghost" className="px-2 py-1.5 text-xs" onClick={() => { setEditing(label); setName(label.name); setColor(label.color); }}>Edit</Button><Button variant="danger" className="px-2 py-1.5 text-xs" onClick={() => remove.mutate({ roomId: state.room.id, labelId: label.id, data: { ownerId: id } }, { onSuccess: () => refreshRoom(state.room.id) })}>Delete</Button></div>)}</div><form onSubmit={save} className="space-y-3"><input value={name} onChange={(event) => setName(event.target.value)} placeholder="Add a label" className="w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3" /><div className="flex gap-2">{labelPalette.map((item) => <button type="button" key={item} onClick={() => setColor(item)} className={`h-7 w-7 rounded-full ${color === item ? "ring-2 ring-[#302f48] ring-offset-2" : ""}`} style={{ backgroundColor: item }} aria-label={`Use ${item}`} />)}</div><div className="flex gap-2"><Button type="submit" disabled={create.isPending || update.isPending} className="flex-1">{editing ? "Save label" : "Add label"}</Button>{editing && <Button type="button" variant="ghost" onClick={() => { setEditing(undefined); setName(""); }}>Cancel</Button>}</div></form></div></div>; }

function TaskEditor({ state, task, onClose }: { state: GameState; task?: Quest; onClose: () => void }) {
  const id = meId(); const [title, setTitle] = useState(task?.title ?? ""); const [notes, setNotes] = useState(task?.notes ?? ""); const [scheduled, setScheduled] = useState(Boolean(task?.dueDate ?? !task)); const [dueDate, setDueDate] = useState(task?.dueDate ?? today); const [labelId, setLabelId] = useState(task?.labelId ?? ""); const [links, setLinks] = useState<QuestLink[]>(task?.links ?? []); const [subtasks, setSubtasks] = useState<QuestSubtask[]>(task?.subtasks ?? []); const [newLink, setNewLink] = useState(""); const [newSubtask, setNewSubtask] = useState(""); const [labelEditor, setLabelEditor] = useState(false); const create = useCreateQuest(); const update = useUpdateQuest(); const labels = state.labels.filter((label) => label.ownerId === id);
  const save = (event: FormEvent) => { event.preventDefault(); if (!title.trim()) return; const data = { ownerId: id, title: title.trim(), notes: notes.trim(), dueDate: scheduled ? dueDate : null, labelId: labelId || null, links, subtasks }; const done = () => { refreshRoom(state.room.id); onClose(); }; task ? update.mutate({ roomId: state.room.id, questId: task.id, data }, { onSuccess: done }) : create.mutate({ roomId: state.room.id, data }, { onSuccess: done }); };
  const pending = create.isPending || update.isPending; return <div className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-[#24243b]/55 p-4"><div className="my-5 w-full max-w-lg rounded-3xl bg-[#fffaf1] p-6"><div className="flex justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{task ? "Edit task" : "New task"}</p><h2 className="font-display text-2xl font-bold">{task ? "Update the details" : "Add a task"}</h2></div><Button variant="ghost" onClick={onClose}>Cancel</Button></div><form onSubmit={save} className="mt-5 space-y-4"><label className="block text-sm font-bold">Task title<input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3" /></label><label className="block text-sm font-bold">Notes<textarea value={notes} onChange={(event) => setNotes(event.target.value)} rows={2} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3" /></label><div><span className="text-sm font-bold">Timing</span><div className="mt-2 flex rounded-xl bg-[#eee5d5] p-1 text-xs font-bold"><button type="button" onClick={() => setScheduled(true)} className={`flex-1 rounded-lg py-2 ${scheduled ? "bg-[#302f48] text-white" : ""}`}>Scheduled date</button><button type="button" onClick={() => setScheduled(false)} className={`flex-1 rounded-lg py-2 ${!scheduled ? "bg-[#302f48] text-white" : ""}`}>Someday</button></div>{scheduled && <input type="date" value={dueDate} onChange={(event) => setDueDate(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-2.5" />}</div><div><div className="flex justify-between text-sm font-bold"><span>Label</span><button type="button" onClick={() => setLabelEditor(true)} className="text-[#9a7a2b]">Manage labels</button></div><select value={labelId} onChange={(event) => setLabelId(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-2.5"><option value="">No label</option>{labels.map((label) => <option key={label.id} value={label.id}>{label.name}</option>)}</select></div><div><p className="text-sm font-bold">Links</p><div className="mt-2 flex gap-2"><input value={newLink} onChange={(event) => setNewLink(event.target.value)} placeholder="https://…" className="min-w-0 flex-1 rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-3 py-2" /><Button type="button" variant="ghost" className="px-3" onClick={() => { if (newLink.trim()) { setLinks([...links, { id: crypto.randomUUID(), url: newLink.trim(), name: newLink.trim() }]); setNewLink(""); } }}>Add link</Button></div>{links.map((link) => <div key={link.id} className="mt-2 flex items-center gap-2 text-xs"><span className="flex-1 truncate">{link.url}</span><button type="button" onClick={() => setLinks(links.filter((item) => item.id !== link.id))} className="font-bold text-[#9f433e]">Delete</button></div>)}</div><div><p className="text-sm font-bold">Subtasks</p><div className="mt-2 flex gap-2"><input value={newSubtask} onChange={(event) => setNewSubtask(event.target.value)} placeholder="Break it down" className="min-w-0 flex-1 rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-3 py-2" /><Button type="button" variant="ghost" className="px-3" onClick={() => { if (newSubtask.trim()) { setSubtasks([...subtasks, { id: crypto.randomUUID(), title: newSubtask.trim(), completed: false }]); setNewSubtask(""); } }}>Add step</Button></div>{subtasks.map((item) => <div key={item.id} className="mt-2 flex items-center gap-2 text-xs"><span className="flex-1">{item.title}</span><button type="button" onClick={() => setSubtasks(subtasks.filter((sub) => sub.id !== item.id))} className="font-bold text-[#9f433e]">Delete</button></div>)}</div><div className="flex gap-2"><Button type="submit" disabled={pending} className="flex-1">{pending ? <Loader2 className="animate-spin" /> : "Save task"}</Button>{!task && <Button type="button" variant="secondary" disabled={pending} onClick={() => { const fake = { preventDefault: () => {} } as FormEvent; save(fake); }} className="flex-1">Save &amp; add another</Button>}</div></form>{labelEditor && <LabelEditor state={state} onDone={() => setLabelEditor(false)} />}</div></div>;
}

function TaskEditor2({ state, task, onClose }: { state: GameState; task?: Quest; onClose: () => void }) {
  const id = meId();
  const [title, setTitle] = useState(task?.title ?? "");
  const [notes, setNotes] = useState(task?.notes ?? "");
  const [scheduled, setScheduled] = useState(Boolean(task?.dueDate ?? !task));
  const [dueDate, setDueDate] = useState(task?.dueDate ?? today);
  const [labelId, setLabelId] = useState(task?.labelId ?? "");
  const [links, setLinks] = useState<QuestLink[]>(task?.links ?? []);
  const [subtasks, setSubtasks] = useState<QuestSubtask[]>(task?.subtasks ?? []);
  const [linkName, setLinkName] = useState("");
  const [linkUrl, setLinkUrl] = useState("");
  const [subtaskTitle, setSubtaskTitle] = useState("");
  const [labelEditor, setLabelEditor] = useState(false);
  const create = useCreateQuest();
  const update = useUpdateQuest();
  const labels = state.labels.filter((label) => label.ownerId === id);
  const submit = (event: FormEvent, addAnother = false) => {
    event.preventDefault();
    if (!title.trim()) return;
    const data = { ownerId: id, title: title.trim(), notes: notes.trim(), dueDate: scheduled ? dueDate : null, labelId: labelId || null, links, subtasks };
    const done = () => {
      refreshRoom(state.room.id);
      if (addAnother && !task) {
        setTitle(""); setNotes(""); setScheduled(true); setDueDate(today); setLabelId(""); setLinks([]); setSubtasks([]);
      } else onClose();
    };
    if (task) update.mutate({ roomId: state.room.id, questId: task.id, data }, { onSuccess: done });
    else create.mutate({ roomId: state.room.id, data }, { onSuccess: done });
  };
  return <div className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-[#24243b]/55 p-4"><div className="my-5 w-full max-w-lg rounded-3xl bg-[#fffaf1] p-6"><div className="flex justify-between"><div><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{task ? "Edit task" : "New task"}</p><h2 className="font-display text-2xl font-bold">{task ? "Update the details" : "Add a task"}</h2></div><Button variant="ghost" onClick={onClose}>Cancel</Button></div><form onSubmit={(event) => submit(event)} className="mt-5 space-y-4"><label className="block text-sm font-bold">Task title<input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3" /></label><label className="block text-sm font-bold">Notes<textarea value={notes} onChange={(event) => setNotes(event.target.value)} rows={2} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-3" /></label><div><span className="text-sm font-bold">Timing</span><div className="mt-2 flex rounded-xl bg-[#eee5d5] p-1 text-xs font-bold"><button type="button" onClick={() => setScheduled(true)} className={`flex-1 rounded-lg py-2 ${scheduled ? "bg-[#302f48] text-white" : ""}`}>Scheduled date</button><button type="button" onClick={() => setScheduled(false)} className={`flex-1 rounded-lg py-2 ${!scheduled ? "bg-[#302f48] text-white" : ""}`}>Someday</button></div>{scheduled && <input type="date" value={dueDate} onChange={(event) => setDueDate(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-2.5" />}</div><div><div className="flex justify-between text-sm font-bold"><span>Label</span><button type="button" onClick={() => setLabelEditor(true)} className="text-[#9a7a2b]">Manage labels</button></div><select value={labelId} onChange={(event) => setLabelId(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fffdf8] px-4 py-2.5"><option value="">No label</option>{labels.map((label) => <option key={label.id} value={label.id}>{label.name}</option>)}</select></div><div><p className="text-sm font-bold">Links</p><div className="mt-2 grid gap-2 sm:grid-cols-[.8fr_1fr_auto]"><input value={linkName} onChange={(event) => setLinkName(event.target.value)} placeholder="Display name" className="rounded-xl border border-[#d9cfbd] px-3 py-2 text-sm" /><input value={linkUrl} onChange={(event) => setLinkUrl(event.target.value)} placeholder="https://…" className="rounded-xl border border-[#d9cfbd] px-3 py-2 text-sm" /><Button type="button" variant="ghost" className="px-3" onClick={() => { if (linkUrl.trim()) { setLinks([...links, { id: crypto.randomUUID(), url: linkUrl.trim(), name: linkName.trim() || linkUrl.trim() }]); setLinkName(""); setLinkUrl(""); } }}>Add link</Button></div>{links.map((link) => <div key={link.id} className="mt-2 flex items-center gap-2 text-xs"><span className="flex-1 truncate">{link.name} · {link.url}</span><Button type="button" variant="danger" className="px-2 py-1 text-xs" onClick={() => setLinks(links.filter((item) => item.id !== link.id))}>Delete</Button></div>)}</div><div><p className="text-sm font-bold">Subtasks</p><div className="mt-2 flex gap-2"><input value={subtaskTitle} onChange={(event) => setSubtaskTitle(event.target.value)} placeholder="Break it down" className="min-w-0 flex-1 rounded-xl border border-[#d9cfbd] px-3 py-2 text-sm" /><Button type="button" variant="ghost" className="px-3" onClick={() => { if (subtaskTitle.trim()) { setSubtasks([...subtasks, { id: crypto.randomUUID(), title: subtaskTitle.trim(), completed: false }]); setSubtaskTitle(""); } }}>Add step</Button></div>{subtasks.map((item) => <div key={item.id} className="mt-2 flex items-center gap-2 text-xs"><span className="flex-1">{item.title}</span><Button type="button" variant="danger" className="px-2 py-1 text-xs" onClick={() => setSubtasks(subtasks.filter((sub) => sub.id !== item.id))}>Delete</Button></div>)}</div><div className="flex gap-2"><Button type="submit" disabled={create.isPending || update.isPending} className="flex-1">Save task</Button>{!task && <Button type="button" disabled={create.isPending} variant="secondary" onClick={(event) => submit(event, true)} className="flex-1">Save &amp; add another</Button>}</div></form>{labelEditor && <LabelEditor state={state} onDone={() => setLabelEditor(false)} />}</div></div>;
}

function RewardSetter({ state, quest }: { state: GameState; quest: Quest }) { const [custom, setCustom] = useState(""); const setReward = useSetQuestReward(); const choose = (value: number) => setReward.mutate({ roomId: state.room.id, questId: quest.id, data: { actorId: meId(), coinValue: value } }, { onSuccess: () => refreshRoom(state.room.id) }); return <div className="mt-3 rounded-xl border border-[#e3c979] bg-[#fff4cc] p-3"><p className="text-xs font-extrabold uppercase tracking-wide text-[#93752c]">Set reward for {ownerOf(state, quest.ownerId)?.name}</p><div className="mt-2 flex flex-wrap gap-2">{[10, 20, 30].map((value) => <Button key={value} disabled={setReward.isPending} onClick={() => choose(value)} className="px-3 py-2 text-xs">{value} coins</Button>)}<div className="flex gap-1"><input value={custom} onChange={(event) => setCustom(event.target.value)} type="number" min="1" step="1" placeholder="Custom" className="w-24 rounded-lg border border-[#d9cfbd] px-2 text-xs" /><Button disabled={setReward.isPending || !Number.isInteger(Number(custom)) || Number(custom) < 1} onClick={() => choose(Number(custom))} className="px-3 py-2 text-xs">Set custom</Button></div></div></div>; }

function TaskCard({ state, quest, own, onEdit, onDelete, onComplete }: { state: GameState; quest: Quest; own: boolean; onEdit?: () => void; onDelete?: () => void; onComplete?: () => void }) {
  const label = state.labels.find((item) => item.id === quest.labelId); const owner = ownerOf(state, quest.ownerId); const update = useUpdateQuest(); const subtasks = quest.subtasks ?? []; const doneSteps = subtasks.filter((item) => item.completed).length; const toggleSubtask = (id: string) => update.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: quest.ownerId, subtasks: subtasks.map((item) => item.id === id ? { ...item, completed: !item.completed } : item) } }, { onSuccess: () => refreshRoom(state.room.id) }); return <article className="rounded-2xl border border-[#dfd3c1] border-l-4 p-4" style={{ borderLeftColor: playerColor(owner, state.players), backgroundColor: label ? `${label.color}22` : "#fffaf1" }}><div className="flex items-start gap-3"><div className="mt-0.5 grid h-7 w-7 place-items-center rounded-full text-[10px] font-extrabold text-white" style={{ backgroundColor: playerColor(owner, state.players) }}>{initials(owner?.name ?? "?").slice(0, 1)}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className={`font-bold ${quest.status === "completed" ? "line-through opacity-60" : ""}`}>{quest.title}</h3>{label && <span className="rounded-md px-2 py-0.5 text-[10px] font-extrabold" style={{ color: label.color, backgroundColor: `${label.color}22` }}>{label.name}</span>}<span className="text-xs text-muted-foreground">{owner?.name}</span></div>{quest.notes && <p className="mt-1 text-xs leading-5 text-muted-foreground">{quest.notes}</p>}<div className="mt-3 flex flex-wrap items-center gap-3 text-[11px] font-semibold text-muted-foreground"><span>{quest.dueDate ? dateLabel(quest.dueDate) : "Someday"}</span><span className="text-[#ad7d1e]">{quest.rewardStatus === "pending" ? "Reward pending" : `+${quest.coinValue} coins`}</span>{subtasks.length > 0 && <span>{doneSteps}/{subtasks.length} steps</span>}</div>{quest.links?.length > 0 && <div className="mt-3 flex flex-wrap gap-2">{quest.links.map((link) => <a key={link.id} href={link.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 rounded-lg bg-[#eee2d2] px-2 py-1 text-xs font-bold text-[#5f5a69] hover:underline"><Link2 className="h-3 w-3" />{link.name || link.url}</a>)}</div>}{subtasks.length > 0 && <div className="mt-3 space-y-1">{subtasks.map((item) => <label key={item.id} className={`flex items-center gap-2 text-xs ${own ? "cursor-pointer" : ""}`}><input type="checkbox" checked={item.completed} disabled={!own || update.isPending} onChange={() => toggleSubtask(item.id)} />{item.title}</label>)}</div>}{quest.status === "completed" && quest.rewardStatus === "pending" && <p className="mt-3 rounded-lg bg-[#f0e8da] px-2.5 py-2 text-xs font-bold text-[#93752c]">Completed – reward pending</p>}{!own && quest.rewardStatus === "pending" && <RewardSetter state={state} quest={quest} />}</div>{own && <div className="flex shrink-0 gap-1"><Button variant="ghost" className="px-2 py-1.5 text-xs" onClick={onEdit}><Pencil className="h-3.5 w-3.5" />Edit task</Button><Button variant="danger" className="px-2 py-1.5 text-xs" onClick={onDelete}>Delete</Button></div>}</div>{own && <div className="mt-4"><Button variant={quest.status === "completed" ? "ghost" : "secondary"} className="px-3 py-2 text-xs" onClick={onComplete}>{quest.status === "completed" ? "Reopen task" : "Mark as completed"}</Button></div>}</article>;
}

function UpdatesPage({ state }: { state: GameState }) { const [editor, setEditor] = useState(false); const id = meId(); const attentionTasks = state.quests.filter((quest) => quest.ownerId !== id && quest.rewardStatus === "pending"); const attentionRewards = state.rewardRequests.filter((request) => request.turnPlayerId === id || (request.status === "accepted" && request.payerId === id)); const recent = [...state.encouragements.map((item) => ({ id: item.id, text: `${ownerOf(state, item.fromId)?.name ?? "Buddy"} sent an encouragement`, date: item.createdAt })), ...state.quests.filter((quest) => quest.status === "completed" && quest.completedAt).map((quest) => ({ id: quest.id, text: `${ownerOf(state, quest.ownerId)?.name ?? "Player"} completed ${quest.title}`, date: quest.completedAt ?? quest.createdAt }))].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 8); return <><PageHeader eyebrow="Home / Updates" title="Needs your attention" body="A shared inbox for rewards to set, deals to answer, and recent activity." action={<Button onClick={() => setEditor(true)}><Plus className="h-4 w-4" /> Add task</Button>} /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="space-y-4">{attentionTasks.length === 0 && attentionRewards.length === 0 && <Empty icon={Check} title="You’re caught up" body="Nothing needs a decision right now." />}{attentionTasks.map((quest) => <TaskCard key={quest.id} state={state} quest={quest} own={false} />)}{attentionRewards.map((request) => <div key={request.id} className="rounded-2xl border border-[#e3c979] bg-[#fff4cc] p-4"><p className="text-xs font-extrabold uppercase tracking-wide text-[#93752c]">Reward request</p><p className="mt-1 font-bold">{request.title}</p><p className="mt-1 text-sm text-muted-foreground">{request.status === "accepted" ? `Accepted – ${ownerOf(state, request.payerId)?.name} must confirm payment.` : `${ownerOf(state, request.turnPlayerId)?.name} must respond at ${request.offer} coins.`}</p><Link href="/rewards" className="mt-3 inline-flex text-xs font-bold text-[#9a7a2b] hover:underline">Open reward requests <ArrowRight className="ml-1 h-3 w-3" /></Link></div>)}</section><aside className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6"><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Recent updates</h2><Zap className="h-5 w-5 text-[#c4962b]" /></div><div className="mt-5 space-y-3">{recent.map((item) => <div key={item.id} className="border-l-2 border-[#d79b4c] pl-3"><p className="text-sm font-bold">{item.text}</p><p className="mt-1 text-xs text-muted-foreground">{new Date(item.date).toLocaleDateString()}</p></div>)}{recent.length === 0 && <p className="text-sm text-muted-foreground">Activity will appear here as both players take actions.</p>}</div></aside></div>{editor && <TaskEditor2 state={state} onClose={() => setEditor(false)} />}</>; }

function TasksPage({ state }: { state: GameState }) { const [editor, setEditor] = useState(false); const [edit, setEdit] = useState<Quest>(); const own = state.quests.filter((quest) => quest.ownerId === meId()); const complete = useSetQuestCompleted(); const remove = useDeleteQuest(); const refresh = () => refreshRoom(state.room.id); const action = (quest: Quest) => complete.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: meId(), completed: quest.status !== "completed" } }, { onSuccess: refresh }); return <><PageHeader eyebrow="Personal tasks" title="My tasks" body="Keep the task details yours. Your buddy sets the reward." action={<Button onClick={() => { setEdit(undefined); setEditor(true); }}><Plus className="h-4 w-4" /> Add task</Button>} /><div className="space-y-6"><section><h2 className="mb-3 font-display text-2xl font-bold">Scheduled</h2><div className="space-y-3">{own.filter((quest) => quest.dueDate).map((quest) => <TaskCard key={quest.id} state={state} quest={quest} own onComplete={() => action(quest)} onEdit={() => { setEdit(quest); setEditor(true); }} onDelete={() => window.confirm("Delete this task?") && remove.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: meId() } }, { onSuccess: refresh })} />)}</div></section><section><h2 className="mb-3 font-display text-2xl font-bold">Someday</h2><p className="mb-3 text-sm text-muted-foreground">No deadline, no overdue state, no daily progress impact.</p><div className="space-y-3">{own.filter((quest) => !quest.dueDate).map((quest) => <TaskCard key={quest.id} state={state} quest={quest} own onComplete={() => action(quest)} onEdit={() => { setEdit(quest); setEditor(true); }} onDelete={() => window.confirm("Delete this task?") && remove.mutate({ roomId: state.room.id, questId: quest.id, data: { ownerId: meId() } }, { onSuccess: refresh })} />)}</div></section></div>{editor && <TaskEditor2 state={state} task={edit} onClose={() => setEditor(false)} />}</>; }

function JourneyPage({ state }: { state: GameState }) { const days = Array.from({ length: 15 }, (_, index) => shiftDate(today, index - 4)); const [selected, setSelected] = useState(today); const details = state.quests.filter((quest) => quest.dueDate === selected); const bar = (player: Player, date: string) => { const tasks = state.quests.filter((quest) => quest.ownerId === player.id && quest.dueDate === date); const complete = tasks.filter((quest) => quest.status === "completed").length; return { tasks, complete, percent: tasks.length ? complete / tasks.length * 100 : 0 }; }; return <><PageHeader eyebrow="Day by day" title="Journey" body="Two separate bars. One player’s progress never moves the other’s." /><div className="space-y-3">{days.map((date) => <button key={date} onClick={() => setSelected(date)} className={`w-full rounded-2xl border p-4 text-left transition ${selected === date ? "border-[#c4962b] bg-[#fffaf1] shadow-sm" : "border-[#dfd3c1] bg-[#f8f1e5] hover:bg-[#fffaf1]"}`}><div className="flex items-center justify-between"><span className="font-display text-lg font-bold">{date === today ? "Today" : dateLabel(date)}</span>{date === today && <span className="rounded-full bg-[#f7ca56] px-2 py-1 text-[10px] font-extrabold uppercase">Current</span>}</div><div className="mt-3 space-y-3">{state.players.map((player) => { const progress = bar(player, date); return <div key={player.id}><div className="mb-1 flex items-center justify-between text-xs font-bold"><span style={{ color: playerColor(player, state.players) }}>{player.name}</span><span className="text-muted-foreground">{progress.tasks.length ? `${progress.complete}/${progress.tasks.length}` : "No tasks planned"}</span></div>{progress.tasks.length > 0 && <div className="relative h-3 rounded-full bg-[#e1d8ca]"><div className="h-full rounded-full" style={{ width: `${progress.percent}%`, backgroundColor: playerColor(player, state.players) }} /><span className="absolute right-0 top-[-3px] h-5 w-1 rounded-full bg-[#302f48]" /></div>}</div>; })}</div></button>)}</div><section className="mt-6 rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6"><p className="font-mono-ui text-[10px] tracking-[.2em] text-[#9a7a2b] uppercase">{selected === today ? "Today" : dateLabel(selected)}</p><h2 className="mt-2 font-display text-2xl font-bold">Day details</h2><div className="mt-4 space-y-3">{details.map((quest) => <TaskCard key={quest.id} state={state} quest={quest} own={quest.ownerId === meId()} />)}{details.length === 0 && <p className="text-sm text-muted-foreground">No scheduled tasks for this day.</p>}</div></section></>; }

function CalendarPage({ state }: { state: GameState }) { const [view, setView] = useState<"week" | "month">("week"); const [anchor, setAnchor] = useState(today); const start = view === "week" ? shiftDate(anchor, -(dateAtNoon(anchor).getDay() === 0 ? 6 : dateAtNoon(anchor).getDay() - 1)) : `${anchor.slice(0, 7)}-01`; const count = view === "week" ? 7 : new Date(dateAtNoon(start).getFullYear(), dateAtNoon(start).getMonth() + 1, 0).getDate(); const days = Array.from({ length: count }, (_, index) => shiftDate(start, index)); return <><PageHeader eyebrow="Shared planning" title="Calendar" body="Both players’ tasks, with ownership kept clear." action={<div className="flex rounded-xl bg-[#eee5d5] p-1 text-xs font-bold"><button onClick={() => setView("week")} className={`rounded-lg px-3 py-2 ${view === "week" ? "bg-[#302f48] text-white" : ""}`}>Week</button><button onClick={() => setView("month")} className={`rounded-lg px-3 py-2 ${view === "month" ? "bg-[#302f48] text-white" : ""}`}>Month</button></div>} /><div className="mb-4 flex items-center justify-between"><Button variant="ghost" onClick={() => setAnchor(shiftDate(anchor, view === "week" ? -7 : -30))}><ChevronLeft /> Previous</Button><span className="font-mono-ui text-xs">{view === "week" ? weekLabel(start) : dateAtNoon(start).toLocaleDateString(undefined, { month: "long", year: "numeric" })}</span><Button variant="ghost" onClick={() => setAnchor(shiftDate(anchor, view === "week" ? 7 : 30))}>Next <ChevronRight /></Button></div><div className={`grid gap-3 ${view === "week" ? "md:grid-cols-2 xl:grid-cols-3" : "sm:grid-cols-2 lg:grid-cols-4"}`}>{days.map((date) => <article key={date} className="rounded-2xl border border-[#dfd3c1] bg-[#fffaf1] p-4"><h2 className="font-bold">{date === today ? "Today" : dateLabel(date)}</h2><div className="mt-3 space-y-2">{state.quests.filter((quest) => quest.dueDate === date).map((quest) => <div key={quest.id} className="border-l-4 pl-2 text-xs" style={{ borderColor: playerColor(ownerOf(state, quest.ownerId), state.players) }}><p className="font-bold">{quest.title}</p><p className="text-muted-foreground">{ownerOf(state, quest.ownerId)?.name} · {quest.status === "completed" ? "Completed" : "Planned"}</p></div>)}{state.quests.every((quest) => quest.dueDate !== date) && <p className="text-xs text-muted-foreground">No tasks planned</p>}</div></article>)}</div></>; }

function RewardRequestCard({ state, request }: { state: GameState; request: RewardRequest }) { const [offer, setOffer] = useState(String(request.offer)); const respond = useRespondToRewardRequest(); const id = meId(); const waiting = request.turnPlayerId === id && !["accepted", "paid", "declined"].includes(request.status); const send = (action: "accept" | "counter" | "decline" | "pay") => respond.mutate({ roomId: state.room.id, requestId: request.id, data: { actorId: id, action, ...(action === "counter" ? { offer: Number(offer) } : {}) } }, { onSuccess: () => refreshRoom(state.room.id) }); return <article className="rounded-2xl border border-[#dfd3c1] bg-[#fffaf1] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-bold">{request.title}</p><p className="mt-1 text-xs text-muted-foreground">Requested by {ownerOf(state, request.requesterId)?.name} · payer: {ownerOf(state, request.payerId)?.name}</p></div><span className="rounded-full bg-[#eee2c6] px-2.5 py-1 text-[10px] font-extrabold uppercase">{request.status === "paid" ? "Paid" : request.status === "accepted" ? "Accepted – waiting for payer" : request.status}</span></div><p className="mt-3 text-sm"><strong>{request.offer} coins</strong> current offer · {request.status === "accepted" ? `${ownerOf(state, request.payerId)?.name} must confirm payment` : `turn: ${ownerOf(state, request.turnPlayerId)?.name}`}</p>{waiting && <div className="mt-4 flex flex-wrap gap-2"><Button onClick={() => send("accept")} className="px-3 py-2 text-xs">Accept offer</Button><div className="flex w-full gap-2 sm:w-auto"><input value={offer} onChange={(event) => setOffer(event.target.value)} type="number" min="1" step="1" className="w-24 rounded-xl border border-[#d9cfbd] px-2 text-sm" aria-label="Counteroffer amount" /><Button variant="ghost" onClick={() => send("counter")} className="px-3 py-2 text-xs">Send counteroffer</Button></div><Button variant="danger" onClick={() => send("decline")} className="px-3 py-2 text-xs">Decline</Button></div>}{request.status === "accepted" && request.payerId === id && <Button onClick={() => send("pay")} className="mt-4">Confirm &amp; pay {request.offer} coins</Button>}</article>; }

function RewardsPage({ state }: { state: GameState }) { const [editor, setEditor] = useState<Reward>(); const [form, setForm] = useState(false); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [cost, setCost] = useState("20"); const [requestForm, setRequestForm] = useState(false); const [requestTitle, setRequestTitle] = useState(""); const [requestOffer, setRequestOffer] = useState("60"); const [requestDescription, setRequestDescription] = useState(""); const id = meId(); const me = ownerOf(state, id); const create = useCreateReward(); const update = useUpdateReward(); const remove = useDeleteReward(); const redeem = useRedeemReward(); const createRequest = useCreateRewardRequest(); const active = state.rewards.filter((reward) => reward.active); const saveReward = (event: FormEvent) => { event.preventDefault(); if (!title.trim()) return; const done = () => { setForm(false); refreshRoom(state.room.id); }; editor ? update.mutate({ roomId: state.room.id, rewardId: editor.id, data: { actorId: id, title: title.trim(), description: description.trim() || null, cost: Number(cost) } }, { onSuccess: done }) : create.mutate({ roomId: state.room.id, data: { createdBy: id, title: title.trim(), description: description.trim(), cost: Number(cost) } }, { onSuccess: done }); }; const sendRequest = (event: FormEvent) => { event.preventDefault(); if (!requestTitle.trim()) return; createRequest.mutate({ roomId: state.room.id, data: { requesterId: id, title: requestTitle.trim(), description: requestDescription.trim() || null, offer: Number(requestOffer) } }, { onSuccess: () => { setRequestForm(false); refreshRoom(state.room.id); } }); }; return <><PageHeader eyebrow="Shared favours" title="Rewards" body="Reusable rewards stay in the shop. One-off deals move through negotiation." action={<div className="flex flex-wrap gap-2"><Button variant="ghost" onClick={() => setRequestForm(true)}><Sparkles className="h-4 w-4" /> Request a favour</Button><Button onClick={() => { setEditor(undefined); setTitle(""); setDescription(""); setCost("20"); setForm(true); }}><Plus className="h-4 w-4" /> Add reward</Button></div>} /><section><h2 className="mb-4 font-display text-2xl font-bold">Available rewards</h2>{active.length ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{active.map((reward) => <article key={reward.id} className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-5"><div className="flex justify-between"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#302f48] text-[#f7ca56]"><Star /></div><div className="flex gap-1"><Button variant="ghost" className="px-2 py-1.5 text-xs" onClick={() => { setEditor(reward); setTitle(reward.title); setDescription(reward.description ?? ""); setCost(String(reward.cost)); setForm(true); }}>Edit</Button><Button variant="danger" className="px-2 py-1.5 text-xs" onClick={() => remove.mutate({ roomId: state.room.id, rewardId: reward.id, data: { actorId: id } }, { onSuccess: () => refreshRoom(state.room.id) })}>Delete</Button></div></div><h3 className="mt-5 font-display text-xl font-bold">{reward.title}</h3><p className="mt-2 min-h-10 text-sm text-muted-foreground">{reward.description}</p><div className="mt-5 flex items-center justify-between border-t border-[#e8dfd1] pt-4"><span className="flex items-center gap-1 font-mono-ui text-[#ad7d1e]"><Gem className="h-4 w-4" />{reward.cost}</span><Button disabled={(me?.coins ?? 0) < reward.cost || redeem.isPending} onClick={() => redeem.mutate({ roomId: state.room.id, rewardId: reward.id, data: { playerId: id } }, { onSuccess: () => refreshRoom(state.room.id) })}>{(me?.coins ?? 0) >= reward.cost ? "Buy reward" : "Need more coins"}</Button></div></article>)}</div> : <Empty icon={Trophy} title="No rewards yet" body="Add a reusable favour for both players to work toward." action={<Button onClick={() => setForm(true)}>Add reward</Button>} />}</section><section className="mt-10"><h2 className="mb-4 font-display text-2xl font-bold">Active / Pending</h2><div className="space-y-3">{state.rewardRequests.filter((request) => !["paid", "declined"].includes(request.status)).map((request) => <RewardRequestCard key={request.id} state={state} request={request} />)}{state.rewardRequests.filter((request) => !["paid", "declined"].includes(request.status)).length === 0 && <p className="rounded-2xl border border-dashed border-[#d7cbb8] bg-[#f8f1e5] p-4 text-sm text-muted-foreground">No active negotiations.</p>}</div></section><section className="mt-10"><h2 className="mb-4 font-display text-2xl font-bold">Completed / Archive</h2><div className="space-y-2">{state.rewardRequests.filter((request) => request.status === "paid").map((request) => <div key={request.id} className="rounded-xl border border-[#dfd3c1] bg-[#fffaf1] p-4 text-sm"><p className="font-bold">{request.title}</p><p className="mt-1 text-xs text-muted-foreground">{ownerOf(state, request.payerId)?.name} paid {request.offer} coins · {new Date(request.updatedAt).toLocaleDateString()}</p></div>)}{state.rewardRequests.filter((request) => request.status === "paid").length === 0 && <p className="rounded-2xl border border-dashed border-[#d7cbb8] bg-[#f8f1e5] p-4 text-sm text-muted-foreground">Purchased favours will stay here permanently.</p>}</div></section>{(form || requestForm) && <div className="fixed inset-0 z-50 grid place-items-center bg-[#24243b]/55 p-4"><div className="w-full max-w-md rounded-3xl bg-[#fffaf1] p-6">{form ? <form onSubmit={saveReward} className="space-y-4"><div className="flex justify-between"><h2 className="font-display text-2xl font-bold">{editor ? "Edit reward" : "Add reward"}</h2><Button type="button" variant="ghost" onClick={() => setForm(false)}>Cancel</Button></div><label className="block text-sm font-bold">Reward name<input value={title} onChange={(event) => setTitle(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] px-4 py-3" /></label><label className="block text-sm font-bold">Description<textarea value={description} onChange={(event) => setDescription(event.target.value)} rows={2} className="mt-2 w-full rounded-xl border border-[#d9cfbd] px-4 py-3" /></label><label className="block text-sm font-bold">Coin cost<input type="number" min="1" value={cost} onChange={(event) => setCost(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] px-4 py-3" /></label><Button type="submit" className="w-full">Save reward</Button></form> : <form onSubmit={sendRequest} className="space-y-4"><div className="flex justify-between"><h2 className="font-display text-2xl font-bold">Request a favour</h2><Button type="button" variant="ghost" onClick={() => setRequestForm(false)}>Cancel</Button></div><label className="block text-sm font-bold">What are you requesting?<input value={requestTitle} onChange={(event) => setRequestTitle(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] px-4 py-3" /></label><label className="block text-sm font-bold">Context<textarea value={requestDescription} onChange={(event) => setRequestDescription(event.target.value)} rows={2} className="mt-2 w-full rounded-xl border border-[#d9cfbd] px-4 py-3" /></label><label className="block text-sm font-bold">Offer<input type="number" min="1" step="1" value={requestOffer} onChange={(event) => setRequestOffer(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] px-4 py-3" /></label><Button type="submit" className="w-full">Send request</Button></form>}</div></div>}</>; }

function TogetherPage({ state }: { state: GameState }) { return <><PageHeader eyebrow="Accountability" title="Together" body="Each player has their own colour and their own task controls." /><div className="grid gap-5 lg:grid-cols-2">{state.players.map((player) => { const own = player.id === meId(); const tasks = state.quests.filter((quest) => quest.ownerId === player.id); const done = tasks.filter((quest) => quest.status === "completed").length; return <section key={player.id} className="rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-5" style={{ borderTopColor: player.color, borderTopWidth: 4 }}><div className="flex items-center gap-3"><Avatar player={player} players={state.players} size="lg" /><div><h2 className="font-display text-2xl font-bold">{player.name}</h2><p className="text-xs text-muted-foreground">{done}/{tasks.length} completed · {player.coins} coins</p></div></div><div className="mt-5 space-y-3">{tasks.map((quest) => <TaskCard key={quest.id} state={state} quest={quest} own={own} />)}</div></section>; })}</div></>; }
function SettingsPage({ state }: { state: GameState }) { const [, setLocation] = useLocation(); const [copied, setCopied] = useState(false); return <><PageHeader eyebrow="Room settings" title="Settings" body="Invite your buddy and keep the room details handy." /><section className="max-w-2xl rounded-3xl border border-[#dfd3c1] bg-[#fffaf1] p-6"><div className="flex items-start gap-4"><Landmark /><div className="flex-1"><p className="text-xs font-bold text-muted-foreground">Current room</p><h2 className="mt-1 font-display text-2xl font-bold">{state.room.name}</h2><div className="mt-5 flex flex-wrap items-center gap-2"><span className="rounded-lg bg-[#eee2d2] px-3 py-2 font-mono-ui tracking-[.15em]">{state.room.code}</span><Button variant="ghost" onClick={() => { navigator.clipboard?.writeText(state.room.code); setCopied(true); }}> <Copy className="h-4 w-4" />{copied ? "Copied" : "Copy code"}</Button><Button variant="ghost" onClick={() => navigator.clipboard?.writeText(inviteLink(state.room.id))}><Link2 className="h-4 w-4" />Copy invite link</Button></div></div></div><div className="mt-6 flex items-center gap-3 rounded-xl bg-[#f0e8da] p-4 text-sm"><LockKeyhole className="text-[#4e8069]" /> Exactly two players can access this room.</div><Button variant="danger" className="mt-6" onClick={() => { localStorage.removeItem("quest-road-room"); localStorage.removeItem("quest-road-player"); setLocation("/"); }}>Leave room</Button></section></>; }

function RoomPage() { const { roomId = "" } = useParams<{ roomId: string }>(); const room = useGetRoom(roomId, { query: { queryKey: getGetRoomQueryKey(roomId), refetchInterval: 8000 } }); const state = useGetGameState(roomId, { query: { queryKey: getGetGameStateQueryKey(roomId), refetchInterval: 8000 } }); useEffect(() => { if (roomId) localStorage.setItem("quest-road-room", roomId); }, [roomId]); if (room.isLoading) return <Loading text="Opening your room…" />; if (room.isError || !room.data) return <ErrorState retry={() => room.refetch()} />; if (room.data.status === "waiting") return <main className="min-h-[100dvh] bg-[#24243b] p-6 text-white"><div className="mx-auto max-w-xl rounded-3xl bg-[#fff7e8] p-8 text-[#24243b]"><p className="font-mono-ui text-xs uppercase text-[#9a7a2b]">Room created</p><h1 className="mt-2 font-display text-3xl font-bold">{room.data.name}</h1><p className="mt-6 rounded-2xl bg-[#302f48] p-5 text-center font-mono-ui text-3xl tracking-[.2em] text-[#f7ca56]">{room.data.code}</p><p className="mt-6 text-center text-sm text-muted-foreground">Share the code or invite link. This page checks for your buddy.</p></div></main>; if (state.isLoading) return <Loading />; if (state.isError || !state.data) return <ErrorState retry={() => state.refetch()} />; return <Shell state={state.data}><UpdatesPage state={state.data} /></Shell>; }

function InvitePage() { const { roomId = "" } = useParams<{ roomId: string }>(); const [, setLocation] = useLocation(); const room = useGetRoom(roomId, { query: { queryKey: getGetRoomQueryKey(roomId), refetchInterval: 8000 } }); const join = useJoinRoom(); const [name, setName] = useState(""); if (room.isLoading) return <Loading text="Opening the invite…" />; if (room.isError || !room.data) return <ErrorState retry={() => room.refetch()} />; if (room.data.status === "playing") return <main className="min-h-[100dvh] bg-[#f3ecdf] p-8"><Empty icon={Compass} title="This room is already full" body="Ask your buddy to open the room from their device." action={<Link href="/"><Button>Back to Quest Buddies</Button></Link>} /></main>; return <main className="min-h-[100dvh] bg-[#24243b] p-5"><div className="mx-auto mt-16 max-w-md rounded-3xl bg-[#fff7e8] p-7 text-[#24243b]"><p className="font-mono-ui text-xs uppercase text-[#9a7a2b]">Join Quest Buddies</p><h1 className="mt-2 font-display text-3xl font-bold">{room.data.name}</h1><form onSubmit={(event) => { event.preventDefault(); if (!name.trim()) return; join.mutate({ roomId, data: { code: room.data.code, playerName: name.trim() } }, { onSuccess: (joined) => { localStorage.setItem("quest-road-room", joined.id); localStorage.setItem("quest-road-player", joined.guest?.id ?? ""); setLocation(`/room/${joined.id}`); } }); }} className="mt-6 space-y-4"><label className="block text-sm font-bold">Your name<input autoFocus value={name} onChange={(event) => setName(event.target.value)} className="mt-2 w-full rounded-xl border border-[#d9cfbd] bg-[#fbf5eb] px-4 py-3" /></label><Button type="submit" disabled={join.isPending} className="w-full">{join.isPending ? <Loader2 className="animate-spin" /> : "Join room"}</Button></form></div></main>; }

function RoutedApp() { const roomId = localStorage.getItem("quest-road-room") ?? ""; const shared = useGetGameState(roomId, { query: { enabled: Boolean(roomId), queryKey: getGetGameStateQueryKey(roomId), refetchInterval: 8000 } }); const page = (element: ReactNode) => !roomId ? <main className="min-h-[100dvh] bg-[#f3ecdf] p-8"><Empty icon={Link2} title="No room selected" body="Create or join a room first." action={<Link href="/"><Button>Find a room</Button></Link>} /></main> : shared.isLoading ? <Loading /> : shared.isError || !shared.data ? <ErrorState retry={() => shared.refetch()} /> : <Shell state={shared.data}>{element}</Shell>; return <Switch><Route path="/" component={HomePage} /><Route path="/room/:roomId" component={RoomPage} /><Route path="/invite/:roomId" component={InvitePage} /><Route path="/today">{page(shared.data ? <UpdatesPage state={shared.data} /> : null)}</Route><Route path="/tasks">{page(shared.data ? <TasksPage state={shared.data} /> : null)}</Route><Route path="/journey">{page(shared.data ? <JourneyPage state={shared.data} /> : null)}</Route><Route path="/calendar">{page(shared.data ? <CalendarPage state={shared.data} /> : null)}</Route><Route path="/rewards">{page(shared.data ? <RewardsPage state={shared.data} /> : null)}</Route><Route path="/together">{page(shared.data ? <TogetherPage state={shared.data} /> : null)}</Route><Route path="/settings">{page(shared.data ? <SettingsPage state={shared.data} /> : null)}</Route><Route component={NotFound} /></Switch>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><Router base={import.meta.env.BASE_URL.replace(/\/$/, "")}><ErrorBoundary resetKey={useLocation()[0]}><RoutedApp /></ErrorBoundary></Router><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;